from pathlib import Path
import subprocess,os,signal,json
repo=Path('/Users/steventran/jobpipe');base='3447fb079b463a43d5dc59bb68e35f4f129475a1'
def git(*a):return subprocess.run(['git',*a],cwd=repo,capture_output=True,text=True,check=True).stdout.strip()
if git('rev-parse','HEAD')!=base:raise SystemExit('AUTHORITY_CHANGED')
code=r'''
import asyncio,json
from playwright.async_api import async_playwright
from tools.live_ats_inspect import allowed_url
url="https://jobs.lever.co/ethena/f85bcfd1-8d2c-4cf5-a6ab-1c8ddab14c65/apply"
js=r"""els=>els.filter(e=>!['hidden','password'].includes((e.type||'').toLowerCase())).map(e=>{
const clean=s=>(s||'').replace(/\s+/g,' ').trim().slice(0,180);
const lab=clean((e.labels&&Array.from(e.labels).map(x=>x.innerText).join(' '))||e.getAttribute('aria-label')||'');
if(lab && !/^(yes|no)$/i.test(lab)) return null;
const a=[];let node=e;
for(let n=0;n<5&&node;n++,node=node.parentElement){
const child=[...node.children].filter(x=>x!==e && !x.contains(e)).slice(0,7).map(x=>({tag:x.tagName.toLowerCase(),cls:clean(x.className && typeof x.className==='string'?x.className:'').slice(0,80),text:clean(x.innerText)})).filter(x=>x.text).slice(0,4);
a.push({tag:node.tagName.toLowerCase(),cls:clean(node.className && typeof node.className==='string'?node.className:'').slice(0,80),role:node.getAttribute('role')||'',child});
}
return {type:(e.type||e.tagName).toLowerCase(),label:lab,ancestors:a};
}).filter(Boolean).slice(0,14)"""
async def main():
 async with async_playwright() as pw:
  b=await pw.chromium.launch(headless=True)
  try:
   page=await b.new_page(accept_downloads=False)
   async def guard(route):
    if route.request.is_navigation_request() and not allowed_url(route.request.url):await route.abort()
    else:await route.continue_()
   await page.route("**/*",guard)
   response=await page.goto(url,wait_until="domcontentloaded",timeout=25000)
   await page.wait_for_timeout(2500)
   if not allowed_url(page.url):raise RuntimeError('UNAPPROVED_REDIRECT')
   findings=await page.locator("input,select,textarea").evaluate_all(js)
   print(json.dumps({"http_status":response.status if response else None,"ambiguous_control_structures":findings,"read_only":True,"submission":"not_attempted","auth":"not_attempted"},sort_keys=True))
  finally:await b.close()
asyncio.run(main())
'''
p=subprocess.Popen([str(repo/'.venv/bin/python'),'-c',code],cwd=repo,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True)
try:o,e=p.communicate(timeout=75)
except subprocess.TimeoutExpired:
 os.killpg(p.pid,signal.SIGKILL);raise SystemExit('TIMEOUT')
print('EXIT',p.returncode,'OUTPUT',o[-15000:],'ERROR',e[-700:],flush=True)
if p.returncode:raise SystemExit('DOM_DIAGNOSTIC_FAILED')
r=json.loads(o)
assert r['http_status']==200 and r['read_only'] and r['submission']=='not_attempted' and r['auth']=='not_attempted'
assert isinstance(r['ambiguous_control_structures'],list) and len(r['ambiguous_control_structures'])>0
assert git('rev-parse','HEAD')==base
print('READONLY_LEVER_CONTEXT_EVIDENCE_OK',flush=True)
